void imprimirTotal(List<? extends Number> lista) {
    double total = 0;
    for (Number n : lista) {
        total += n.doubleValue();
    }
    System.out.println(total);
}

imprimirTotal(List.of(1, 2, 3));       // List<Integer>, OK
imprimirTotal(List.of(1.5, 2.5));      // List<Double>, OK

