List<String> nombres = new ArrayList<>(List.of("Ana", "Bob", "Carla", "Dora"));
for (String n : nombres) {
    if (n.equals("Bob")) {
        nombres.remove(n); // ConcurrentModificationException
    }
}

List<Integer> numeros = new ArrayList<>(List.of(1, 2, 3, 4));
try {
    for (Integer n : numeros) {
        if (n == 2) numeros.remove(n);
    }
} catch (ConcurrentModificationException e) {
    System.out.println("capturada");
}

